import type {NotebookEntry} from '../shared/notebook';
import {useDraftPresence} from './draft-presence';
import { Stickers, StickerImage } from './Stickers';
import { BrowserPanel } from './BrowserPanel';
import { BudgetField, ModelPricing } from './ModelPricing';
import { formatCny } from '../shared/pricing';
import { ModelPicker, type CatalogLoader } from './ModelPicker';
import { MemberLibrary, ProfileSelection } from './MemberLibrary';
import {BillingPanel} from './BillingPanel';
import { SubscriptionPanel, type LocalApi } from './SubscriptionPanel';
import { MentionInput } from './MentionInput';
import { MemberUsagePanel, RoomJournal } from './RoomJournal';
import { containsMention, inferredMentions } from '../shared/mentions';
import { Avatar } from './Avatar';
import { AvatarPicker, avatarFileData, type AvatarUploader } from './AvatarPicker';
import type { ModelCatalog } from '../shared/model-catalog';
import { useExchangeRate } from './currency';
import { connectRoomEvents } from './live-connection';
import { ConversationMode, FreeChatControls, FreeChatStatus, FreeSettingsForm, SkillLibrary, SkillPicker } from './FreeChatPanel';
import { defaultFreeSettings, type SkillSummary } from '../shared/free-chat';
import { BookOpen, Archive, ArrowRight, Check, ChevronRight, CircleHelp, Copy, Download, Ellipsis, ExternalLink, FileInput, Hash, History, Leaf, LoaderCircle, LockKeyhole, Menu, MessageCircle, Pencil, Play, Plus, RefreshCw, Send, Smile, Settings2, ShieldCheck, SlidersHorizontal, Square, Trash2, Users, X } from 'lucide-react';
import { identityModeOf, connectionKey, memberConnection, resolveConnection, profileFields, profileParticipant, type MemberProfile, WEB_CHAT_URLS, type Bootstrap, type DiscussionSettings, type Group, type GroupDetail, type Message, type Participant, type PendingWebTurn, type ProviderConfig, type ProviderId } from '../shared/types';


const names: Record<ProviderId, string> = { demo: '本地演示', openai: 'OpenAI', claude: 'Claude', deepseek: 'DeepSeek', qwen: '通义千问', doubao: '豆包', ollama: 'Ollama' };
const marks: Record<ProviderId, string> = { demo: '茶', openai: 'O', claude: 'C', deepseek: 'D', qwen: 'Q', doubao: '豆', ollama: 'O' };
const colors = ['#34705a', '#ad785a', '#5579b1', '#8572ae', '#ae8b45', '#6c8792'];
const runLabels: Record<string, string> = { running: '讨论进行中', awaiting_web: '等待浏览器连接', waiting: '稍候，下一位即将发言', completed: '本次讨论已完成', cancelled: '讨论已停止', failed: '讨论遇到问题', interrupted: '讨论已中断' };

function Brand({ small = false }: { small?: boolean }) {
  return <svg className={small ? 'brand-icon small' : 'brand-icon'} viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M9 17h20v7a10 10 0 0 1-20 0v-7Z" stroke="currentColor" strokeWidth="2"/><path d="M29 18h2a5 5 0 0 1 0 10h-3M8 35h24M16 11c-3-4 4-4 1-8M23 11c-3-4 4-4 1-8" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/><path d="M13 22c3 0 5 4 10 1" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>;
}

function Modal({ title, subtitle, children, close, wide = false }: { title: string; subtitle?: string; children: ReactNode; close: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { const el = ref.current; el?.showModal(); return () => el?.close(); }, []);
  return <dialog ref={ref} className={`modal ${wide ? 'wide' : ''}`} onCancel={close} onClick={e => { if (e.target === e.currentTarget) close(); }}><div className="modal-shell"><header className="modal-header"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" onClick={close} aria-label="关闭对话框"><X size={20}/></button></header>{children}</div></dialog>;
}

function Field({ label, children, help }: { label: string; children: ReactNode; help?: string }) {
  return <label className="field"><span>{label}</span>{children}{help && <small>{help}</small>}</label>;
}

export default function App() {
  const exchangeRate = useExchangeRate();
  const [boot, setBoot] = useState<Bootstrap | null>(null);
  const [selected, setSelected] = useState('');
  const [notebookScope,setNotebookScope]=useState<string|null>(null);
  const [notebookEntries,setNotebookEntries]=useState<NotebookEntry[]>([]);
  const [notebookRevision,setNotebookRevision]=useState(0);
  const [selectionDraft,setSelectionDraft]=useState<SelectionDraft|null>(null);
  const [annotationEditing,setAnnotationEditing]=useState(false);
  const [noteJump,setNoteJump]=useState<NotebookEntry|null>(null);

  const selectedRef = useRef('');
  const [detail, setDetail] = useState<GroupDetail | null>(null);
  const [error, setError] = useState('');
  const [toast, setToast] = useState('');
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const draftsRef = useRef<Record<string, string>>({});
  const mentionDraftsRef = useRef<Record<string,string[]>>({});
  const typingRef=useRef(0);
  const updateDraft = (value: string) => {
    draftsRef.current[selectedRef.current] = value;setMessage(value);
    void publishDraft(selectedRef.current,value.length>0);
    if(value.trim()&&Date.now()-typingRef.current>4000){typingRef.current=Date.now();void api('/api/groups/'+selectedRef.current+'/typing','POST',{}).catch(()=>{});}
  };
  const [archived, setArchived] = useState(false);
  const [search, setSearch] = useState('');
  const [mobilePanel, setMobilePanel] = useState<'groups' | 'settings' | null>(null);
  const [smallViewport, setSmallViewport] = useState(() => window.matchMedia('(max-width: 700px)').matches);
  const [modal, setModal] = useState<'new' | 'edit' | 'provider' | 'member' | 'help' | 'browser' | 'skills' | 'library' | 'invite' | 'stickers' | 'sticker-picker' | 'logs' | null>(null);
  const [member, setMember] = useState<Participant | null>(null);
  const [memberScope, setMemberScope] = useState<'group' | 'library' | 'invite'>('group');
  const [tab, setTab] = useState<'members' | 'settings'>('members');
  const [exportMenu, setExportMenu] = useState(false);
  const [connection, setConnection] = useState(true);
  const [reconnectAttempt, setReconnectAttempt] = useState(0);
  const bottomRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const followScroll = useRef(true);
  const csrfRef = useRef('');
  const sequenceRef = useRef(0);
  const [clock, setClock] = useState(Date.now());

  const api = useCallback(async <T,>(path: string, method = 'GET', body?: unknown): Promise<T> => {
    const response = await fetch(path, { method, headers: { ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}), ...(method !== 'GET' ? { 'X-CSRF-Token': csrfRef.current } : {}) }, ...(body !== undefined ? { body: JSON.stringify(body) } : {}), credentials: 'same-origin' });
    const data = await response.json().catch(() => ({ error: '服务返回了无法识别的内容' }));
    if (!response.ok) throw new Error(data.error || `请求失败 (${response.status})`);
    return data as T;
  }, []);

  const publishDraft=useDraftPresence(api,draftsRef,boot?.groups??[],csrfRef,setError);
  useEffect(()=>{
    setSelectionDraft(null);setAnnotationEditing(false);
  },[selected]);
  useEffect(()=>{
    let cancelled=false;
    const load=()=>{if(!selected){setNotebookEntries([]);return;}void api<NotebookEntry[]>('/api/notebook?groupId='+encodeURIComponent(selected)).then(entries=>{if(!cancelled)setNotebookEntries(entries);}).catch(e=>{if(!cancelled)setError(e.message);});};
    setNotebookEntries([]);load();window.addEventListener('focus',load);
    return()=>{cancelled=true;window.removeEventListener('focus',load);};
  },[api,selected,notebookRevision]);
  useEffect(()=>{
    if(!noteJump||detail?.group.id!==noteJump.groupId)return;
    const element=document.getElementById('message-'+noteJump.anchor?.messageId);
    if(element){followScroll.current=false;element.scrollIntoView({block:'center',behavior:'instant'});element.classList.add('note-jump');setNoteJump(null);setTimeout(()=>element.classList.remove('note-jump'),2500);}
  },[noteJump,detail]);
  const loadModels = useCallback<CatalogLoader>((id, region, refresh = false) => api<ModelCatalog>(`/api/providers/${id}/models`, 'POST', { region, refresh }), [api]);

  const refresh = useCallback(async (id?: string) => {
    const sequence = ++sequenceRef.current;
    const data = await api<Bootstrap>('/api/bootstrap');
    if (sequence !== sequenceRef.current) return;
    csrfRef.current = data.csrfToken;
    setBoot(data);
    const choice = id ?? (selectedRef.current || data.groups.find(g => !g.archived)?.id || data.groups[0]?.id || '');
    if (choice) {
      const group = await api<GroupDetail>(`/api/groups/${encodeURIComponent(choice)}`);
      if (sequence !== sequenceRef.current) return;
      selectedRef.current = choice; setSelected(choice); setDetail(group);
    } else if (sequence === sequenceRef.current) { setDetail(null); setSelected(''); selectedRef.current = ''; }
  }, [api]);

  useEffect(() => { void refresh().catch(() => setConnection(false)); }, [refresh]);
  useEffect(() => {
    const media = window.matchMedia('(max-width: 700px)');
    const update = () => setSmallViewport(media.matches);
    update(); media.addEventListener('change', update);
    return () => media.removeEventListener('change', update);
  }, []);
  useEffect(() => connectRoomEvents(refresh, setConnection), [refresh, reconnectAttempt]);
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(''), 3000); return () => clearTimeout(t); }, [toast]);
  useEffect(() => { if (followScroll.current && !noteJump && detail?.messages.length) bottomRef.current?.scrollIntoView({ behavior: 'instant' }); }, [detail?.messages,noteJump]);
  useEffect(() => { const t = setInterval(() => setClock(Date.now()), 1000); return () => clearInterval(t); }, []);

  const action = async (operation: () => Promise<unknown>, notice?: string) => {
    setBusy(true); setError('');
    try { await operation(); await refresh(); if (notice) setToast(notice); }
    catch (e) { setError(e instanceof Error ? e.message : '操作失败，请重试'); }
    finally { setBusy(false); }
  };
  const selectGroup = (id: string) => { selectedRef.current = id; setSelected(id); setDetail(null); setMessage(draftsRef.current[id] || ''); setMobilePanel(null); followScroll.current = true; void refresh(id).catch(e => setError(e.message)); };
  const patchGroup = async (patch: Partial<Group>) => { await api(`/api/groups/${selectedRef.current}`, 'PATCH', patch); };
  const saveSettings = (patch: Partial<Group>, asDefault=false) => action(async () => {
    if (!detail) return;
    if (asDefault) { const g={...detail.group,...patch}; await api(`/api/groups/${g.id}/default-template`, 'POST', {conversationMode:g.conversationMode??'round',settings:g.settings,freeSettings:{...defaultFreeSettings,...g.freeSettings}}); }
    else await patchGroup(patch);
  }, asDefault?'已设为新群默认模板，当前设置也已保存':detail?.group.conversationMode==='free'?'自主群聊设置已保存':'讨论设置已保存');
  const updateParticipants = (participants: Participant[]) => action(() => patchGroup({ participants }), '成员设置已保存');
  const send = async () => {
    if (!message.trim() || busy || !detail) return;
    const value = message.trim(); const draft = message; const groupId = selected;
    await action(async () => {
      await api(`/api/groups/${groupId}/messages`, 'POST', { content: value, mentions: [...new Set([...(mentionDraftsRef.current[groupId]??[]).filter(id=>detail.group.participants.some(p=>p.id===id&&p.enabled&&containsMention(value,p.name))),...inferredMentions(value,detail.group.participants)])] });
      if (draftsRef.current[groupId] === draft) { draftsRef.current[groupId] = ''; void publishDraft(groupId,false,'sent',true); mentionDraftsRef.current[groupId]=[]; if (selectedRef.current === groupId) setMessage(''); }
    });
  };
  const start = (body: { targetId?: string; summaryOnly?: boolean } = {}) => action(async () => {await publishDraft(selected,(draftsRef.current[selected]?.length??0)>0,'edit',true);return api(`/api/groups/${selected}/${detail?.group.conversationMode === 'free' && !body.targetId && !body.summaryOnly ? 'free/start' : 'runs'}`, 'POST', body);});
  const exportConversation = (format: 'md' | 'json') => {
    if (!detail) return;
    const content = format === 'json' ? JSON.stringify(detail, null, 2) : `# ${detail.group.name}\n\n> ${detail.group.goal}\n\n${detail.messages.map(m => `## ${m.author} · ${m.kind === 'summary' ? '总结' : m.discussionMode === 'free' ? '自主群聊' : m.round ? `第 ${m.round} 轮` : '参与者发言'}\n\n消息 ID：${m.id}\n\n${m.content}${m.sticker ? `\n\n[表情包：${m.sticker.name}；标签：${m.sticker.tags.join('、')}]` : ''}${m.reasoning ? `\n\n<details>\n<summary>${m.reasoningLabel || '回答依据'}</summary>\n\n${m.reasoning}\n\n</details>` : ''}\n`).join('\n---\n\n')}`;
    const url = URL.createObjectURL(new Blob([content], { type: format === 'json' ? 'application/json;charset=utf-8' : 'text/markdown;charset=utf-8' }));
    const a = document.createElement('a'); a.href = url; a.download = `${detail.group.name.replace(/[<>:"/\\|?*]/g, '_')}.${format}`; a.click(); URL.revokeObjectURL(url); setExportMenu(false); setToast('已导出讨论记录');
  };
  const group = detail?.group;
  const active = detail?.activeRun;
  const freeMode = group?.conversationMode === 'free';
  const freeSession = detail?.freeSession;
  const roomActive = !!active || freeSession?.status === 'active';
  const freeSettings = { ...defaultFreeSettings, ...group?.freeSettings };
  const usage = freeMode && !active ? freeSession : active || detail?.runs[0];
  const activeMembers=group?.participants.filter(p=>p.enabled)??[];const onlySubscription=activeMembers.length>0&&activeMembers.every(p=>p.channel!=='browser'&&resolveConnection(boot?.providers??[],p)?.billingMode==='subscription');
  const lastRun = detail?.runs[0];
  const run = active || lastRun;
  const visibleGroups = boot?.groups.filter(g => g.archived === archived && g.name.toLowerCase().includes(search.toLowerCase())) || [];
  const enabledMembers = group?.participants.filter(p => p.enabled) || [];
  const waiting = active?.nextAt ? Math.max(0, Math.ceil((new Date(active.nextAt).getTime() - clock) / 1000)) : 0;

  return <div className="app-shell">
    <nav className="rail" aria-label="主导航"><div className="rail-brand" title="Chat 茶馆"><Brand/></div><button className="rail-button selected" title="圆桌群聊" aria-label="圆桌群聊" onClick={() => setMobilePanel(null)}><MessageCircle size={23}/></button><button className="rail-button" title="笔记本" aria-label="笔记本" onClick={()=>setNotebookScope('all')}><BookOpen size={22}/></button><button className="rail-button" title="AI 成员库" aria-label="AI 成员库" onClick={() => setModal('library')}><Users size={22}/></button><button className="rail-button" title="模型连接" aria-label="模型连接" onClick={() => setModal('provider')}><SlidersHorizontal size={22}/></button><button className="rail-button" title="浏览器连接" aria-label="浏览器连接" onClick={() => setModal('browser')}><ExternalLink size={22}/></button><button className="rail-button" title="管理表情包" aria-label="管理表情包" onClick={()=>setModal('stickers')}><Smile size={22}/></button><div className="rail-spacer"/><button className="rail-button" title="使用指南" aria-label="使用指南" onClick={() => setModal('help')}><CircleHelp size={22}/></button><span className="local-avatar" title="本地工作空间">我</span></nav>
    {mobilePanel && <button className="drawer-shade" onClick={() => setMobilePanel(null)} aria-label="关闭侧栏"/>}
    <aside className={`groups-panel ${mobilePanel === 'groups' ? 'mobile-open' : ''}`} inert={smallViewport && mobilePanel !== 'groups'} aria-hidden={smallViewport && mobilePanel !== 'groups'}>
      <header className="workspace-header"><div><h1>chat 茶馆</h1><p>群聊 · 多一种观点</p></div><button className="icon-button mobile-close" onClick={() => setMobilePanel(null)} aria-label="关闭群列表"><X size={18}/></button></header>
      <button className="new-group" onClick={() => setModal('new')}><Plus size={18}/> 新建群聊 <span>＋</span></button>
      <div className="search-wrap"><MessageCircle size={15}/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="搜索群聊" aria-label="搜索群聊"/><span>⌕</span></div>
      <div className="group-section"><span>{archived ? '已归档' : '我的群聊'} <b>{visibleGroups.length}</b></span><button className={`icon-button ${archived ? 'accent' : ''}`} title={archived ? '查看活跃圆桌' : '查看已归档圆桌'} aria-label={archived ? '查看活跃圆桌' : '查看已归档圆桌'} onClick={() => setArchived(!archived)}><Archive size={15}/></button></div>
      <div className="group-list">{visibleGroups.map(g => <button key={g.id} className={`group-item ${selected === g.id ? 'active' : ''}`} onClick={() => selectGroup(g.id)}><span className="group-icon"><Leaf size={20}/></span><span className="group-text"><strong>{g.name}</strong><span>{g.goal || '一张空桌，等一个好问题'}</span><small>{g.participants.filter(p => p.enabled).length} 位 AI <i/> {new Date(g.updatedAt).toLocaleDateString('zh-CN', { month: 'numeric', day: 'numeric' })}</small></span>{selected === g.id && <span className="group-dot"/>}</button>)}{!visibleGroups.length && <p className="list-empty">{search ? '没有找到这张圆桌' : archived ? '暂时没有已归档圆桌' : '新建圆桌，开始一次讨论'}</p>}</div>

      <button className="workspace-footer" onClick={() => setModal('provider')}><span className="security-icon"><ShieldCheck size={17}/></span><span><strong>本地工作空间</strong><small>{connection ? '仅本机访问 · 密钥受保护' : '连接中断 · 正在重连'}</small></span><span className={`connection-dot ${!connection ? 'offline' : ''}`}/></button>
    </aside>
    <main className="chat-panel">
      <header className="chat-header"><button className="icon-button mobile-menu" aria-label="打开圆桌列表" onClick={() => setMobilePanel('groups')}><Menu size={21}/></button><div className="chat-heading"><div className="title-line"><h2>{group?.name || '欢迎来到茶馆'}</h2>{group?.archived && <span className="badge">已归档</span>}<span className="private-label"><LockKeyhole size={11}/> 私人圆桌</span></div><p><span className="tiny-dot"/>{enabledMembers.length} 位 AI · 我也在讨论<span className="subtitle-divider">/</span>{freeMode ? '自主选择发言 · 允许沉默' : group?.settings.contextMode === 'sequential' ? '依次对话' : '首轮独立 · 交叉讨论'}</p></div><div className="chat-header-actions"><button className="icon-button notebook-header-button" title="群聊笔记" aria-label="群聊笔记" disabled={!group} onClick={()=>setNotebookScope(selected)}><BookOpen size={18}/></button><button className="icon-button" title="群聊日志与用量" aria-label="群聊日志与用量" disabled={!group} onClick={()=>setModal('logs')}><History size={18}/></button><button className="icon-button" title="编辑圆桌" aria-label="编辑圆桌" onClick={() => setModal('edit')} disabled={!group}><Pencil size={17}/></button><div className="menu-container"><button className="icon-button" title="导出与归档" aria-label="导出与归档" onClick={() => setExportMenu(!exportMenu)} disabled={!group}><Ellipsis size={21}/></button>{exportMenu && <div className="popup-menu"><button onClick={() => exportConversation('md')}><Download size={15}/>导出 Markdown</button><button onClick={() => exportConversation('json')}><Download size={15}/>导出 JSON</button><button onClick={() => { setExportMenu(false); if (group) void action(() => patchGroup({ archived: !group.archived }), group.archived ? '圆桌已恢复' : '圆桌已归档'); }}><Archive size={15}/>{group?.archived ? '恢复圆桌' : '归档圆桌'}</button></div>}</div><button className="icon-button details-trigger" title="成员与设置" aria-label="成员与设置" onClick={() => setMobilePanel('settings')}><Users size={20}/></button></div></header>
      {!connection && <div className="connection-banner" role="status"><div><strong>连接中断，正在自动重连</strong><span>若持续无法恢复，请重新运行项目中的 Start-Teahouse.cmd。未发送的文字仍留在当前页面。</span></div><button className="secondary-button" onClick={() => setReconnectAttempt(n => n + 1)}><RefreshCw size={14}/>重新连接</button></div>}
      {error && <div className="error-banner" role="alert"><span>{error}</span><button className="icon-button" onClick={() => setError('')} aria-label="关闭错误"><X size={15}/></button></div>}
      {group && <div className="goal-strip"><span className="goal-icon"><Hash size={15}/></span><span><b>本桌议题</b>{group.goal || '从一个问题开始，听听不同的答案。'}</span><button className="icon-button" onClick={() => setModal('edit')} title="修改议题" aria-label="修改议题"><Pencil size={13}/></button></div>}
      <div className="messages" ref={scrollRef} onScroll={() => { const el = scrollRef.current; if (el) followScroll.current = el.scrollHeight - el.scrollTop - el.clientHeight < 150; }}>
        {!detail ? <div className="empty-state"><Brand/><h2>{boot && !boot.groups.length ? '第一张圆桌，留给你的好奇心' : '正在为你沏茶…'}</h2><p>{boot && !boot.groups.length ? '邀请不同的 AI，让一个问题有更多种答案。' : '连接本地工作空间'}</p>{boot && !boot.groups.length && <button className="primary-button" onClick={() => setModal('new')}><Plus size={16}/>新建圆桌</button>}</div> : <>
          <div className="conversation-date"><span/>{new Date(group!.createdAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })} · 圆桌已就绪<span/></div>
          {!detail.messages.length && <div className="chat-intro"><MessageCircle size={27}/><h3>开始一场平等的讨论</h3><p>你可以随时发言。每位成员都可以提出异议，人的观点也需要论证。</p><span>{freeMode ? '先发送想法，再点击「开始讨论」。当前自主群聊支持 API 与本地模型。' : '先发送想法，再点击「开始讨论」。可在右上角邀请 API 或网页成员。'}</span>{enabledMembers.length > 0 && enabledMembers.every(p => p.providerId === 'demo') && <div className="demo-notice"><Leaf size={14}/><span>当前成员使用演示预设内容。<button onClick={() => { setTab('members'); setMobilePanel('settings'); }}>邀请真实模型 <ArrowRight size={12}/></button></span></div>}</div>}
          {detail.messages.map((m, index) => <div key={m.id}>{m.round > 0 && (index === 0 || detail.messages[index - 1].round !== m.round || detail.messages[index - 1].runId !== m.runId) && <div className="round-divider"><span/>{m.kind === 'summary' ? '收拢观点 · 圆桌总结' : `第 ${m.round} 轮 · ${m.round === 1 ? '独立观点' : '交流与回应'}`}<span/></div>}<ChatMessage message={m} annotations={notebookEntries.filter(e=>e.anchor?.messageId===m.id)} select={setSelectionDraft} onCopy={() => { void navigator.clipboard.writeText(m.content).then(() => setToast('已复制回复')).catch(() => setError('复制失败，请手动选择文本复制')); }}/></div>)}
          {active?.pendingWeb && <BrowserTurnCard pending={active.pendingWeb} person={active.participants.find(p=>p.id===active.pendingWeb!.participantId)} start={async()=>{await api('/api/runs/'+active.id+'/browser-start','POST',{requestId:active.pendingWeb!.requestId});await refresh();}} pause={async()=>{await api('/api/runs/'+active.id+'/browser-pause','POST',{requestId:active.pendingWeb!.requestId});await refresh();}} open={async()=>{const p=active.participants.find(p=>p.id===active.pendingWeb!.participantId)!;await api('/api/browser/'+p.providerId+'/open','POST',{});}}/>}
          {active?.status === 'waiting' && <div className="waiting-row"><span className="typing-dots"><i/><i/><i/></span><span>{group?.participants.find(p => p.id === active.nextSpeakerId)?.name || '下一位成员'}{waiting > 0 ? `将在 ${waiting} 秒后发言` : '正在准备发言'}</span></div>}
          {run && !active && !freeMode && <div className={`run-result ${run.status === 'failed' || run.status === 'interrupted' ? 'warning' : ''}`}><span>{run.status === 'completed' ? <Check size={15}/> : <Square size={12}/>} {runLabels[run.status]} · {run.turnCount} 次发言</span>{run.error && <p>{run.error}</p>}{run.status === 'failed' && <button className="text-button" disabled={busy} onClick={() => void action(() => api(`/api/runs/${run.id}/retry`, 'POST', {}))}><RefreshCw size={13}/>重试未完成发言</button>}</div>}
          {freeMode && group && !active && <><FreeChatStatus group={group} session={freeSession} now={clock}/><details className="usage-inline"><summary>查看各成员 Token 与人民币费用</summary><MemberUsagePanel group={group} usage={detail.usage}/></details></>}<div ref={bottomRef}/>
        </>}
      </div>
      {group && <section className="composer-section">{freeMode && !active ? <FreeChatControls key={group.id} group={group} session={freeSession} busy={busy} start={reset => void action(async () => {await publishDraft(selected,(draftsRef.current[selected]?.length??0)>0,'edit',true);return api(`/api/groups/${selected}/free/start`, 'POST', { reset: !!reset });})} pause={() => void action(() => api(`/api/groups/${selected}/free/pause`, 'POST', {}))}/> : <div className="discussion-toolbar"><div className="run-status">{active ? <><span className="live-dot"/><strong>{runLabels[active.status]}</strong><span>第 {active.currentRound} / {active.chosenRounds} 轮</span></> : <><span className="ready-dot"/><span>{group.archived ? '已归档的圆桌' : '圆桌已就绪'}</span><span className="toolbar-sep">·</span><span>{group.settings.roundsMode === 'random' ? `${group.settings.roundsMin}–${group.settings.roundsMax}` : group.settings.rounds} 轮{group.settings.roundsMode === 'random' ? '随机' : '讨论'}</span></>}</div><div className="toolbar-actions">{active ? <button className="stop-button" onClick={() => void action(() => api(`/api/runs/${active.id}/cancel`, 'POST', {}))} disabled={busy}><Square size={11}/>停止讨论</button> : <button className="text-button" onClick={() => void start()} disabled={busy || !enabledMembers.length || group.archived}><Play size={12}/>开始讨论</button>}</div></div>}<div className="composer-box">{freeMode&&group.freeSettings?.waitForUserDraft&&message.length>0&&<p className="draft-wait-notice" role="status">输入框有文字：AI 正在等待你发送或清空；清空后 3 秒恢复。</p>}<MentionInput key={group.id} value={message} change={updateDraft} members={group.participants} disabled={group.archived} placeholder={roomActive ? freeMode ? '加入讨论，或 @一位成员；你的观点也可以被质疑…' : '随时加入讨论；新观点在下一位发言前进入上下文…' : '输入你的观点，输入 @ 选择成员…'} send={()=>void send()} picked={mentionDraftsRef.current[group.id]??[]} onPicked={ids=>{mentionDraftsRef.current[group.id]=ids;}}/><div className="composer-bottom"><div className="composer-tools"><button className="icon-button" title="表情包" aria-label="表情包" disabled={group.archived} onClick={()=>setModal('sticker-picker')}><Smile size={18}/></button><button className="icon-button" title="讨论设置" aria-label="讨论设置" onClick={() => { setTab('settings'); setMobilePanel('settings'); }}><Settings2 size={18}/></button><span className="composer-hint">Enter 发送 · Shift Enter 换行</span></div><button className="send-button" onClick={() => void send()} disabled={busy || !message.trim() || group.archived}>{busy ? <LoaderCircle size={16} className="spinning"/> : <Send size={16}/>}<span>{roomActive ? '加入讨论' : '发送'}</span></button></div></div><p className="composer-disclaimer"><ShieldCheck size={11}/>{freeMode ? '观点都可以质疑。群聊开启时，@ 成员会跳过随机唤醒和冷却；已在思考的成员不会重复启动。' : '所有成员的观点都可以质疑。发送消息不会自动开始新一轮讨论。'}</p></section>}
    </main>
    <aside className={`details-panel ${mobilePanel === 'settings' ? 'mobile-open' : ''}`} inert={mobilePanel !== 'settings'} aria-hidden={mobilePanel !== 'settings'}>
      <header className="details-header"><h3>群聊设置</h3><button className="icon-button mobile-close" onClick={() => setMobilePanel(null)} aria-label="关闭设置"><X size={18}/></button></header>
      <div className="details-tabs"><button className={tab === 'members' ? 'active' : ''} onClick={() => setTab('members')}><Users size={15}/>圆桌成员</button><button className={tab === 'settings' ? 'active' : ''} onClick={() => setTab('settings')}><Settings2 size={15}/>讨论设置</button></div>
      <div className="details-scroll">{group && (tab === 'members' ? <><div className="section-label"><span>参与者 <b>{enabledMembers.length}</b></span><button className="text-button" onClick={() => setModal('invite')} disabled={roomActive}><Plus size={13}/>邀请</button></div><div className="member-list">{group.participants.map(p => <div className={`member-card ${!p.enabled ? 'muted' : ''}`} key={p.id}><div className="member-top"><Avatar person={p} size="small"/><div className="member-name"><strong>{p.name}</strong><span>{p.channel === 'browser' ? '浏览器连接 · 实验自动回复' : p.providerId === 'demo' ? '演示 · 无真实模型' : p.model || names[p.providerId]}</span></div><label className="switch"><input type="checkbox" aria-label={`${p.enabled ? '停用' : '启用'} ${p.name}`} checked={p.enabled} disabled={roomActive || busy} onChange={e => void updateParticipants(group.participants.map(item => item.id === p.id ? { ...item, enabled: e.target.checked } : item))}/><span/></label></div><p>{identityModeOf(p) === 'native' ? '原生模式 · 不附加角色设定' : `角色模式 · ${p.role || '尚未设置角色描述'}`}{!!p.skills?.length && <span> · {p.skills.length} 个技能</span>}</p><div className="member-bottom"><span className={`provider-label ${p.providerId === 'demo' ? 'demo' : ''}`}>{names[p.providerId]}</span><div><button className="icon-button" title={`编辑 ${p.name}`} aria-label={`编辑 ${p.name}`} disabled={roomActive} onClick={() => { setMember(p); setMemberScope('group'); setModal('member'); }}><Pencil size={13}/></button><button className="icon-button" title={`请 ${p.name} 发言`} aria-label={`请 ${p.name} 发言`} disabled={roomActive || !p.enabled || busy || group.archived} onClick={() => void start({ targetId: p.id })}><Play size={13}/></button></div></div></div>)}</div><button className="add-member" onClick={() => setModal('invite')} disabled={roomActive}><Plus size={17}/>邀请一位 AI 入座</button><button className="provider-link" onClick={() => setModal('library')}><Users size={15}/>管理 AI 成员库<ArrowRight size={14}/></button><button className="provider-link" onClick={() => setModal('provider')}><SlidersHorizontal size={15}/>管理模型连接<ArrowRight size={14}/></button><button className="provider-link" onClick={() => setModal('browser')}><ExternalLink size={15}/>管理浏览器连接<ArrowRight size={14}/></button><button className="provider-link" onClick={() => setModal('skills')}><Leaf size={15}/>管理技能库<ArrowRight size={14}/></button><button className="provider-link" onClick={()=>setModal('stickers')}><Smile size={15}/>管理表情包<ArrowRight size={14}/></button><div className="room-guide"><span className="guide-icon"><Leaf size={18}/></span><h4>我也是讨论成员</h4><p>人和 AI 的观点同样需要证据。保留不同意见，也可以修正自己的判断。</p><div><span>可随时发言</span><span>允许质疑</span><span>保留分歧</span></div></div><div className="room-overview"><div><span>讨论方式</span><b>{freeMode ? '自主判断 · 允许等待' : group.settings.contextMode === 'round' ? '独立首轮 · 按轮共享' : '依次共享观点'}</b></div><div><span>发言间隔</span><b>{freeMode ? (freeSettings.messageStyle === 'segmented' ? `${freeSettings.readingCharsPerSecond?`分段按 ${freeSettings.readingCharsPerSecond} 字/秒`:'分段 1 秒'} · 接话 ${freeSettings.messageGapMin}–${freeSettings.messageGapMax} 秒` : `${freeSettings.messageGapMin}–${freeSettings.messageGapMax} 秒 + 阅读缓冲`) : group.settings.delayMode === 'random' ? `${group.settings.delayMin}–${group.settings.delayMax} 秒 · 随机` : `${group.settings.delaySeconds} 秒`}</b></div><div><span>自动总结</span><b>{freeMode ? '可向成员提出请求' : group.settings.autoSummary ? '开启' : '关闭'}</b></div></div>{detail.messages.length > 0 && <button className="secondary-button full" onClick={() => void start({ summaryOnly: true })} disabled={roomActive || busy || group.archived}><Leaf size={14}/>请一位成员总结</button>}</> : <><ConversationMode group={group} disabled={roomActive || busy} save={conversationMode => void action(() => patchGroup({ conversationMode }))}/>{freeMode ? <FreeSettingsForm key={group.id + JSON.stringify(group.freeSettings) + JSON.stringify(group.settings)} group={group} disabled={roomActive || busy} save={saveSettings}/> : <SettingsPanel key={group.id + JSON.stringify(group.settings)} group={group} active={roomActive} busy={busy} save={(settings,asDefault) => saveSettings({settings},asDefault)}/>}</>)}
      </div><footer className="usage-footer"><div><span><History size={13}/>本次用量</span><b>{((usage?.inputTokens || 0) + (usage?.outputTokens || 0)).toLocaleString()} <small>tokens</small></b></div><div><span>{onlySubscription?'官方订阅':'API 预估费用'}</span><b title={onlySubscription?'在群聊日志或模型连接中查看官方共享额度':`按 1 美元 ≈ ${exchangeRate} 元估算，非实时汇率`}>{onlySubscription?'使用套餐额度':formatCny((usage?.estimatedUSD || 0) * exchangeRate)}</b></div><p>{freeMode && !active ? `当前预留 ${(freeSession?.reservedTokens || 0).toLocaleString()} tokens。费用按配置单价估算，实际以供应商账单为准。` : 'API 费用为估算；订阅使用官方额度，见群聊日志或模型连接。网页连接无法计量。'}</p></footer>
    </aside>
    {toast && <div className="toast" role="status"><Check size={16}/>{toast}</div>}
    {notebookScope&&boot&&<NotebookDialog scope={notebookScope} groups={boot.groups} currentGroup={selected} api={api} changed={()=>setNotebookRevision(n=>n+1)} close={()=>setNotebookScope(null)} jump={entry=>{setNotebookScope(null);followScroll.current=false;setNoteJump(entry);if(entry.groupId!==selected){selectGroup(entry.groupId);followScroll.current=false;}}}/>}
    {selectionDraft&&!annotationEditing&&!notebookScope&&!modal&&<SelectionToolbar key={selectionDraft.anchor.messageId+':'+selectionDraft.anchor.start+':'+selectionDraft.anchor.end} draft={selectionDraft} entries={notebookEntries} api={api} changed={(entry,removedId)=>setNotebookEntries(old=>entry?[...old.filter(e=>e.id!==entry.id),entry]:old.filter(e=>e.id!==removedId))} comment={()=>setAnnotationEditing(true)} close={()=>setSelectionDraft(null)}/>}
    {selectionDraft&&annotationEditing&&boot&&<Modal title="我的评论" subtitle="仅自己可见，不会发送到群聊" close={()=>{if(window.confirm('放弃尚未保存的评论？')){setAnnotationEditing(false);setSelectionDraft(null);}}}><NotebookEditor commentOnly initial={selectedAnnotation(notebookEntries,selectionDraft)} draft={selectionDraft} groups={boot.groups} groupId={selectionDraft.groupId} categories={[]} api={api} saved={entry=>{setNotebookEntries(old=>[...old.filter(e=>e.id!==entry.id),entry]);setSelectionDraft(null);setAnnotationEditing(false);window.getSelection()?.removeAllRanges();setToast('评论已保存');}} cancel={()=>{setAnnotationEditing(false);setSelectionDraft(null);}}/></Modal>}
    {(modal === 'new' || modal === 'edit') && <GroupModal profiles={boot?.profiles || []} group={modal === 'edit' ? group : undefined} close={() => setModal(null)} save={async values => { if (modal === 'edit') { await patchGroup(values); await refresh(); } else { const result = await api<Group | GroupDetail>('/api/groups', 'POST', values); const id = 'group' in result ? result.group.id : result.id; selectedRef.current = id; setMessage(draftsRef.current[id] || ''); await refresh(id); setArchived(false); } setModal(null); }}/>}
    {(modal === 'library' || modal === 'invite') && boot && <Modal title={modal === 'invite' ? '邀请 AI 入群' : 'AI 成员库'} subtitle={modal === 'invite' ? '从长期保存的成员中选择。' : '创建一次，在不同群聊中相遇。'} wide close={() => setModal(null)}><MemberLibrary profiles={boot.profiles || []} deletedProfiles={boot.deletedProfiles || []} groups={boot.groups} group={modal === 'invite' ? group : undefined} create={() => { setMember(null); setMemberScope(modal === 'invite' ? 'invite' : 'library'); setModal('member'); }} edit={profile => { setMember(profileParticipant(profile, profile.id)); setMemberScope('library'); setModal('member'); }} invite={async profileId => { await api('/api/groups/' + selectedRef.current + '/members', 'POST', { profileId }); await refresh(); }} remove={async p => { await api('/api/members/' + p.id, 'DELETE', {expectedRevision:p.revision}); await refresh(); }} restore={async p => { await api('/api/members/' + p.id + '/restore', 'POST', {expectedRevision:p.revision}); await refresh(); }}/></Modal>}
    {modal === 'member' && boot && <MemberModal loadModels={loadModels} uploadAvatar={async file => (await api<{id:string}>('/api/avatars', 'POST', {data:await avatarFileData(file)})).id} providers={boot.providers} skills={boot.skills || []} initial={member} close={() => setModal(memberScope === 'library' ? 'library' : memberScope === 'invite' ? 'invite' : null)} save={async p => {
      if (p.profileId) await api('/api/members/' + p.profileId, 'PUT', { profile: profileFields(p), expectedRevision: p.profileRevision });
      else await api('/api/members', 'POST', { profile: profileFields(p), ...(memberScope === 'invite' ? { groupId: selectedRef.current } : {}) });
      await refresh(); setModal(memberScope === 'library' ? 'library' : null);
    }} remove={member && memberScope === 'group' && group ? async () => { await api('/api/groups/' + group.id + '/members/' + member.id, 'DELETE'); await refresh(); setModal(null); } : undefined}/>}
    {modal === 'provider' && boot && <ProviderModal api={api} create={async data=>{const p=await api<ProviderConfig>('/api/providers','POST',data);await refresh();return connectionKey(p);}} remove={async id=>{await api('/api/providers/'+id,'DELETE',{});await refresh();}} loadModels={loadModels} providers={boot.providers} security={boot.security} close={() => setModal(null)} save={async (id, data) => { const saved = await api<ProviderConfig>(`/api/providers/${id}`, 'PUT', data); sequenceRef.current += 1; setBoot(current => current ? { ...current, providers: current.providers.map(p => connectionKey(p) === connectionKey(saved) ? saved : p) } : current); }} test={async id => { const r = await api<{ message?: string; ok?: boolean }>('/api/providers/' + id + '/test', 'POST', {}); if (r.ok === false) throw new Error(r.message || '连接测试失败'); return r.message || '连接成功'; }}/>}
    {(modal==='stickers'||modal==='sticker-picker')&&boot&&<Modal title={modal==='stickers'?'本地表情包库':'发送表情包'} subtitle="名称和标签帮助 AI 理解使用场景" wide close={()=>setModal(null)}><Stickers stickers={boot.stickers||[]} api={api} refresh={()=>refresh()} send={modal==='sticker-picker'&&group?async id=>{await api('/api/groups/'+group.id+'/stickers','POST',{stickerId:id});await refresh();setModal(null);}:undefined}/>{modal==='sticker-picker'&&<button className="text-button sticker-manage-link" onClick={()=>setModal('stickers')}>管理表情包</button>}</Modal>}
    {modal === 'logs' && group && <Modal title="群聊日志与用量" subtitle={group.name} close={()=>setModal(null)} wide><RoomJournal key={group.id} group={group} usage={detail?.usage} api={api} revision={freeSession?.updatedAt??group.updatedAt}/></Modal>}
    {modal === 'skills' && boot && <Modal title="技能库" subtitle="按成员分配 · 按需读取" close={() => setModal(null)}><SkillLibrary skills={boot.skills || []} disabled={roomActive} save={async markdown => { await api('/api/skills', 'POST', { markdown }); await refresh(); }} remove={async id => { await api('/api/skills/' + encodeURIComponent(id), 'DELETE'); await refresh(); }}/></Modal>}
    {modal === 'browser' && <Modal title="浏览器连接" subtitle="专用浏览器 · 本机保存登录状态" wide close={() => setModal(null)}><BrowserPanel api={api}/></Modal>}
    {modal === 'help' && <Modal title="群聊使用指南" subtitle="不同模型，平等讨论。" close={() => setModal(null)}><div className="help-content"><div><b>01 · 两种连接方式</b><p>API 成员支持自主群聊，可分别选择不同的 API 连接。浏览器成员在专用窗口自动输入与读取，暂使用按轮圆桌；页面无法识别或遇到限制时暂停。网页登录与额度由对应网站管理。</p></div><div><b>02 · 原生或角色模式</b><p>原生模式不附加角色和立场，只保留群聊身份、上下文与平等讨论协议。角色模式允许设置观察角度。原生不代表移除供应商默认行为、网页记忆或自定义指令，也不保证展示完整内部思考。</p></div><div><b>03 · 我也是讨论成员</b><p>人的观点不是默认正确的结论，AI 可以质疑、反驳和提出证据。你随时发送的消息会在下一位发言前加入上下文，正在生成的回答不会被重写。发送与开始讨论是分开的操作。</p></div><div><b>04 · 自己决定讨论节奏</b><p>自主群聊中，每位成员拥有独立会话，可以读取消息、发言或选择等待。可设置全群发言间隔、阅读缓冲、输入保护、冷却区间、唤醒概率、并发数和预算；不会在无人说话时反复调用模型。浏览器成员目前使用按轮圆桌，可在讨论设置中切换。</p></div><div><b>05 · 真实来源与用量</b><p>「已读」显示实际送达成员的公开消息。自主群聊的消息折叠区显示工具活动记录。右上角「群聊日志与用量」显示供应商返回的推理内容或摘要、等待原因，以及按成员拆分的 Token 与人民币费用；未提供的推理不会补写。模型的沉默判断也可能产生费用；暂停后继续沿用本次预算，重新开始才会重置。</p></div><div><b>06 · 本机保管</b><p>密钥保存在本机后端，页面只显示配置状态。网页登录留在官方页面，浏览器连接的登录资料仅保存在本机专用浏览器配置中，不通过茶馆接口导出。请勿分享 data 目录。向云模型或官方网页发送讨论内容前，请检查其中的信息。</p></div></div></Modal>}
  </div>;
}

function ChatMessage({ message: m, onCopy, annotations, select }: { message: Message; onCopy: () => void; annotations:NotebookEntry[];select:(value:SelectionDraft)=>void }) {
  const user = m.kind === 'user';
  return <article className={`message-row ${user ? 'user-message' : ''} ${m.kind === 'summary' ? 'summary-message' : ''}`} id={`message-${m.id}`}><Avatar person={m}/><div className="message-main"><div className="message-meta"><strong>{user ? '我 · 讨论成员' : m.author}</strong>{m.source === 'browser' && <span className="badge web">浏览器读取</span>}{m.source === 'web' && <span className="badge web">历史网页导入</span>}{m.providerId === 'demo' && <span className="badge demo">演示</span>}{m.kind === 'import' && <span className="badge">外部导入</span>}{m.kind === 'summary' && <span className="badge summary">圆桌总结</span>}<span className="message-model">{m.model}</span>{m.speech && <span className="badge">连发 {m.speech.index}/{m.speech.total}</span>}<time>{new Date(m.createdAt).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })}</time></div><div className="message-bubble">{m.reasoning && <details className="reasoning"><summary><ChevronRight size={13}/>{m.reasoningLabel || '返回的推理内容 / 摘要'}<span>展开查看</span></summary><div>{m.reasoning}</div></details>}{m.sticker&&<StickerImage sticker={m.sticker}/>}<AnnotatedMessage message={m} entries={annotations} select={select}/>{m.speech?.state === 'interrupted' && <p className="message-status">本次连发已中断，后续段落未发送</p>}{['stopped', 'failed'].includes(m.status) && <p className="message-status">{m.status === 'stopped' ? '已停止生成' : '生成失败，可重试本轮'}</p>}</div><footer className="message-footer">{m.inputMessageIds.length > 0 && <details className="sources"><summary>已读 {m.inputMessageIds.length} 条</summary><div><small>此发言引用的上下文</small>{m.inputMessageIds.map((id, index) => <a key={id} href={`#message-${id}`} title={id}>消息 {index + 1} · {id.slice(0, 8)}</a>)}<small title={m.id}>本条消息 · {m.id.slice(0, 8)}</small></div></details>}<button className="icon-button" aria-label={`复制 ${m.author} 的回复`} title="复制回复" onClick={onCopy}><Copy size={12}/></button></footer></div></article>;
}

function GroupModal({ group, profiles, close, save }: { group?: Group; profiles: MemberProfile[]; close: () => void; save: (data: { name: string; goal: string; profileIds?: string[] }) => Promise<void> }) {
  const [invited, setInvited] = useState<string[]>([]);
  const [name, setName] = useState(group?.name || ''); const [goal, setGoal] = useState(group?.goal || ''); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  return <Modal title={group ? '编辑圆桌' : '为一个好问题，开一张圆桌'} subtitle={group ? '清晰的议题，会让讨论更有方向。' : '设置一个目标，邀请不同的声音。'} close={close}><form className="modal-form" onSubmit={async e => { e.preventDefault(); setSaving(true); try { await save({ name: name.trim(), goal: goal.trim(), ...(!group ? { profileIds: invited } : {}) }); } catch (err) { setError((err as Error).message); } finally { setSaving(false); } }}><Field label="圆桌名称"><input autoFocus required value={name} onChange={e => setName(e.target.value)} placeholder="例如：我的产品灵感室" maxLength={80}/></Field><Field label="讨论目标" help="议题用于确定讨论范围，并不代表预设结论。每位成员都可以质疑其中的假设。"><textarea value={goal} onChange={e => setGoal(e.target.value)} placeholder="我们想讨论什么？希望得到怎样的结果？" rows={4} maxLength={8000}/></Field>{!group && <ProfileSelection profiles={profiles} selected={invited} change={setInvited} disabled={saving}/>}{error && <p className="inline-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="secondary-button" onClick={close}>取消</button><button className="primary-button" disabled={saving || !name.trim()}>{saving ? '保存中…' : group ? '保存修改' : '创建圆桌'}<ArrowRight size={15}/></button></div></form></Modal>;
}

function MemberModal({ initial, providers, skills, close, save, remove, loadModels, uploadAvatar }: { loadModels: CatalogLoader; uploadAvatar:AvatarUploader; initial: Participant | null; providers: ProviderConfig[]; skills: SkillSummary[]; close: () => void; save: (member: Participant) => Promise<void>; remove?: () => Promise<void> }) {
  const first = providers.find(p => p.id === 'demo') || providers[0];
  const [value, setValue] = useState<Participant>(() => initial ? { ...initial, identityMode: identityModeOf(initial), channel: initial.channel || 'api' } : { id: crypto.randomUUID(), name: '', providerId: first.id, model: first.model, avatar: '茶', role: '', color: colors[0], enabled: true, identityMode: 'native', channel: 'api' });
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [confirmDelete, setConfirmDelete] = useState(false);
  const [avatarBusy,setAvatarBusy] = useState(false);
  const apiModels = useRef<Record<string, string>>({ [memberConnection(value)]: value.channel !== 'api' ? providers.find(p => p.id === value.providerId)?.model || '' : value.model });
  const web = value.channel === 'browser';
  const setChannel = (channel: 'api' | 'browser') => {
    if (!web) apiModels.current[memberConnection(value)] = value.model;
    const providerId = channel !== 'api' && !WEB_CHAT_URLS[value.providerId] ? 'openai' : value.providerId;
    setValue({ ...value, channel, providerId, connectionId:undefined, model: channel !== 'api' ? '网页版当前模型' : apiModels.current[providerId] || providers.find(p => p.id === providerId)!.model, avatar: providerId === value.providerId || value.avatar !== marks[value.providerId] ? value.avatar : marks[providerId] });
  };
  const submit = async (operation: () => Promise<void>) => { if(busy||avatarBusy)return;setBusy(true); setError(''); try { await operation(); } catch (err) { setError((err as Error).message); } finally { setBusy(false); } };
  return <Modal title={initial ? '编辑成员档案' : '创建 AI 成员'} subtitle={initial ? '修改会同步到该成员已加入的所有群。' : '长期保存，之后可直接邀请到不同群聊。'} close={close}>
    <form className="modal-form" onSubmit={e => { e.preventDefault(); void submit(() => save({ ...value, name: value.name.trim(), avatar: value.avatar.trim() || marks[value.providerId] })); }}>
      <div className="member-editor-heading"><Avatar person={value}/><div><b>{value.name || '新成员'}</b><p>{names[value.providerId]}</p></div><div className="color-picker">{colors.map(c => <button type="button" aria-label={`选择头像颜色 ${c}`} key={c} className={c === value.color ? 'selected' : ''} style={{ backgroundColor: c }} onClick={() => setValue({ ...value, color: c })}>{c === value.color && <Check size={12}/>}</button>)}</div></div>
      <div className="form-grid"><Field label="显示名称"><input required autoFocus value={value.name} maxLength={40} onChange={e => setValue({ ...value, name: e.target.value })} placeholder="例如：DeepSeek"/></Field><Field label="头像文字"><input value={value.avatar} maxLength={4} onChange={e => setValue({ ...value, avatar: e.target.value })}/></Field></div>
      <AvatarPicker value={value.avatarAssetId} change={avatarAssetId=>setValue(current=>({...current,avatarAssetId}))} upload={uploadAvatar} pending={setAvatarBusy}/>
      <Field label="连接方式"><select value={value.channel} onChange={e => setChannel(e.target.value as 'api' | 'browser')}><option value="api">API / 本地模型 · 自动回复</option><option value="browser">浏览器连接 · 实验自动回复</option></select></Field>
      {value.channel === 'browser' && <div className="channel-note"><ExternalLink size={16}/><p>无需 API Key。先在「管理浏览器连接」的专用窗口登录。开始讨论后会自动尝试发送和读取回复；页面无法识别、验证或额度限制时暂停。仅在平台允许的情况下使用。</p></div>}
      <Field label={web?'模型供应商':'模型供应商 / API 连接'}><select aria-label="模型供应商" value={web?value.providerId:memberConnection(value)} onChange={e=>{const p=providers.find(p=>connectionKey(p)===e.target.value)!;if(!web)apiModels.current[memberConnection(value)]=value.model;setValue({...value,providerId:p.id,connectionId:p.connectionId,model:web?'网页版当前模型':apiModels.current[connectionKey(p)]||p.model,avatar:value.avatar===marks[value.providerId]?marks[p.id]:value.avatar});}}>{providers.filter(p=>!web||!p.connectionId&&WEB_CHAT_URLS[p.id]).map(p=><option key={connectionKey(p)} value={connectionKey(p)}>{names[p.id]}{p.label?' · '+p.label:''}{web?' · 官方网页':p.billingMode==='subscription'?' · 订阅授权':p.hasKey?' · 已配置':p.id==='demo'||p.id==='ollama'?' · 本地':' · 待配置密钥'}</option>)}</select></Field>
      {web ? <Field label="模型名称" help="实际模型由你在官方网页选择，本应用无法自动识别。"><input value={value.model} readOnly/></Field> : <ModelPicker key={memberConnection(value)} label="模型名称" provider={resolveConnection(providers,value) || providers.find(p=>p.id===value.providerId)!} value={value.model} change={model => setValue({ ...value, model })} load={loadModels} disabled={busy}/>}
      <Field label="身份设定"><select value={identityModeOf(value)} onChange={e => setValue({ ...value, identityMode: e.target.value as 'native' | 'role' })}><option value="native">原生模式 · 不附加角色设定</option><option value="role">角色模式 · 自定义身份和观察角度</option></select></Field>
      {identityModeOf(value) === 'native' ? <p className="native-note">不附加人物、立场或角色描述；仅保留群聊所需的身份、上下文和讨论协议。供应商默认行为与网页的个人记忆仍可能影响回复。{value.role && <span>已保留角色草稿，当前不会发送给模型。</span>}</p> : <Field label="角色与观察角度"><textarea value={value.role} maxLength={2000} rows={3} onChange={e => setValue({ ...value, role: e.target.value })} placeholder="例如：关注成本与落地难度，主动指出未经验证的假设。"/></Field>}
      <p className="field-help">成员资料在各群共用。移出本群仍保留档案，历史发言保留当时的名字与头像。</p><SkillPicker skills={skills} value={value.skills || []} change={skills => setValue({ ...value, skills })} disabled={web}/>
      {error && <p className="inline-error" role="alert">{error}</p>}<div className="modal-actions">{remove && <button type="button" className="danger-button" disabled={busy || avatarBusy} onClick={() => { if (confirmDelete) void submit(remove); else setConfirmDelete(true); }}><Trash2 size={14}/>{confirmDelete ? '确认移出本群' : '移出本群'}</button>}<span className="spacer"/><button type="button" className="secondary-button" onClick={close}>取消</button><button className="primary-button" disabled={busy || avatarBusy || !value.name.trim()}>{busy ? '保存中…' : '保存成员'}</button></div>
    </form>
  </Modal>;
}

function BrowserTurnCard({pending,person,start,pause,open}:{pending:PendingWebTurn;person?:Participant;start:()=>Promise<void>;pause:()=>Promise<void>;open:()=>Promise<void>}) {
  const [busy,setBusy]=useState(false),[error,setError]=useState('');const working=pending.browser&&pending.browser.phase!=='paused';
  const action=async(fn:()=>Promise<void>)=>{setBusy(true);setError('');try{await fn();}catch(e){setError((e as Error).message);}finally{setBusy(false);}};
  return <section className="browser-turn-card" aria-label="浏览器回复"><h3>{person?.name} · 浏览器连接</h3><p role="status">{pending.browser?.message||'正在准备网页会话'}</p><div className="browser-actions"><button className="secondary-button" disabled={busy} onClick={()=>void action(open)}>显示专用窗口</button>{working?<button className="secondary-button" disabled={busy} onClick={()=>void action(pause)}>暂停浏览器</button>:<button className="primary-button" disabled={busy} onClick={()=>void action(start)}>新建会话重新发送</button>}</div>{!working&&<p className="field-help">请检查网页登录或页面状态。重新发送会新建会话，未完成的网页请求可能仍在生成。</p>}{error&&<p role="alert" className="inline-error">{error}</p>}</section>;
}

function SettingsPanel({ group, active, busy, save }: { group: Group; active: boolean; busy: boolean; save: (settings: DiscussionSettings,asDefault?:boolean) => Promise<void> }) {
  const [value, setValue] = useState(group.settings); const [dirty, setDirty] = useState(false);
  const update = <K extends keyof DiscussionSettings>(key: K, next: DiscussionSettings[K]) => { setValue(v => ({ ...v, [key]: next })); setDirty(true); };
  const numeric = (key: keyof DiscussionSettings, min: number, max: number, step = 1) => <input type="number" min={min} max={max} step={step} required value={value[key] as number} onChange={e => update(key, e.target.value === '' ? min : Number(e.target.value))}/>;
  return <form className="settings-form" onSubmit={e => { e.preventDefault(); void save(value,(e.nativeEvent as SubmitEvent).submitter?.getAttribute('value')==='default-template'); }}><div className="settings-note"><ShieldCheck size={16}/><p>{active ? '本次讨论使用开始时的设置。请停止后修改。' : '每场讨论都有边界，节奏由你决定。'}</p></div><fieldset disabled={active || busy}><h4>讨论节奏</h4><Field label="上下文共享"><select value={value.contextMode} onChange={e => update('contextMode', e.target.value as 'round' | 'sequential')}><option value="round">按轮共享 · 首轮独立</option><option value="sequential">依次共享 · 首轮仍独立</option></select></Field><Field label="发言顺序"><select value={value.order} onChange={e => update('order', e.target.value as 'fixed' | 'random')}><option value="fixed">固定 · 按成员列表</option><option value="random">随机 · 每轮重新打乱</option></select></Field><Field label="讨论轮次"><select value={value.roundsMode} onChange={e => update('roundsMode', e.target.value as 'fixed' | 'random')}><option value="fixed">固定轮次</option><option value="random">随机轮次</option></select></Field>{value.roundsMode === 'fixed' ? <Field label="轮数">{numeric('rounds', 1, 12)}</Field> : <div className="form-grid"><Field label="最少轮数">{numeric('roundsMin', 1, 12)}</Field><Field label="最多轮数">{numeric('roundsMax', value.roundsMin, 12)}</Field></div>}<Field label="发言间隔"><select value={value.delayMode} onChange={e => update('delayMode', e.target.value as 'fixed' | 'random')}><option value="fixed">固定间隔</option><option value="random">随机间隔</option></select></Field>{value.delayMode === 'fixed' ? <Field label="间隔秒数">{numeric('delaySeconds', 0, 300, 0.1)}</Field> : <div className="form-grid"><Field label="最短秒数">{numeric('delayMin', 0, 300, 0.1)}</Field><Field label="最长秒数">{numeric('delayMax', value.delayMin, 300, 0.1)}</Field></div>}<p className="field-help">间隔从上一位完成后计算。随机轮数在开始时抽取，随机间隔在每次发言前抽取。</p><h4>讨论边界</h4><Field label="单次最大输出 token">{numeric('maxOutputTokens', 128, 8192)}</Field><div className="form-grid"><Field label="最多调用次数">{numeric('maxCalls', 1, 128)}</Field><BudgetField valueUSD={value.budgetUSD} change={usd => update('budgetUSD', usd)}/></div><Field label="累计 token 上限">{numeric('maxTotalTokens', 1000, 1000000, 1000)}</Field><p className="field-help">API 达到限制将结束讨论；浏览器连接受轮次和发言次数限制，无法统计 token 和费用。金额填 0 表示关闭金额保护，仍受调用和 token 限制。开启金额保护时，云端模型必须配置输入与输出费率；估算不等同于最终账单。</p><h4>收拢观点</h4><label className="toggle-field"><span>讨论结束后自动总结</span><span className="switch"><input type="checkbox" checked={value.autoSummary} onChange={e => update('autoSummary', e.target.checked)}/><span/></span></label><Field label="总结成员"><select value={value.summaryParticipantId} onChange={e => update('summaryParticipantId', e.target.value)}><option value="">自动选择首位启用成员</option>{group.participants.filter(p => p.enabled).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><button className="primary-button full" disabled={!dirty || busy}>保存讨论设置<Check size={15}/></button><button className="secondary-button full" type="submit" value="default-template">设为新群默认模板</button><p className="field-help">同时保存当前修改。新群沿用讨论模式、节奏及预算；总结成员由新群自动选择，其他现有群不变。</p></fieldset></form>;
}

function ProviderModal({ api, providers, security, close, save, test, loadModels, create, remove }: { api:LocalApi; loadModels: CatalogLoader; providers: ProviderConfig[]; security: Bootstrap['security']; close: () => void; save: (id: string, data: unknown) => Promise<void>; test: (id: string) => Promise<string>;create:(data:{providerId:ProviderId;label:string})=>Promise<string>;remove:(id:string)=>Promise<void> }) {
  const [selected,setSelected]=useState('openai'),[adding,setAdding]=useState(false),[company,setCompany]=useState<ProviderId>('deepseek'),[label,setLabel]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[confirm,setConfirm]=useState(false);
  const provider=providers.find(p=>connectionKey(p)===selected)||providers[0];
  return <Modal title="模型连接" subtitle="每个连接独立保存密钥、模型和费率，成员可自由选择。" wide close={close}>
    <div className="connection-toolbar"><button className="secondary-button" onClick={()=>{setAdding(!adding);setError('');}}>添加 API 连接</button><small>同一家公司可添加多个连接；一个连接也可供多个独立成员使用。</small></div>
    {adding&&<form className="connection-create" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{const id=await create({providerId:company,label:label.trim()});setSelected(id);setAdding(false);setLabel('');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}><Field label="连接供应商"><select value={company} onChange={e=>setCompany(e.target.value as ProviderId)}>{providers.filter(p=>!p.connectionId&&!['demo','ollama'].includes(p.id)).map(p=><option key={p.id} value={p.id}>{names[p.id]}</option>)}</select></Field><Field label="新连接名称"><input required maxLength={40} value={label} onChange={e=>setLabel(e.target.value)} placeholder="例如：DeepSeek 个人账号"/></Field><button className="primary-button" disabled={busy}>创建连接</button></form>}
    {error&&<p className="inline-error" role="alert">{error}</p>}
    <div className="providers-layout"><nav className="provider-nav" aria-label="模型供应商">{providers.map(p=><button key={connectionKey(p)} className={connectionKey(p)===connectionKey(provider)?'active':''} onClick={()=>{setSelected(connectionKey(p));setConfirm(false);setError('');}}><span>{marks[p.id]}</span>{names[p.id]}{p.label?' · '+p.label:''}<i className={p.hasKey||p.id==='demo'||p.id==='ollama'?'configured':''}/></button>)}</nav><div><ProviderForm api={api} loadModels={loadModels} key={connectionKey(provider)+(provider.billingMode??'api')} provider={provider} save={data=>save(connectionKey(provider),data)} test={()=>test(connectionKey(provider))}/>{provider.connectionId&&<button className="text-button danger" disabled={busy} onClick={async()=>{if(!confirm){setConfirm(true);return;}setBusy(true);setError('');try{await remove(connectionKey(provider));setSelected(provider.id);setConfirm(false);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}>{confirm?'确认删除此连接':'删除此连接'}</button>}</div></div><div className="vault-note"><ShieldCheck size={15}/><span>密钥仅保存在本机加密凭据库，不回传浏览器。{security.vault}。更换连接不会共享成员身份或私有上下文。</span></div></Modal>;
}

function ProviderForm({ api, provider, save, test, loadModels }: { api:LocalApi; loadModels: CatalogLoader; provider: ProviderConfig; save: (data: unknown) => Promise<void>; test: () => Promise<string> }) {
  const [label,setLabel]=useState(provider.label||''); const [model, setModel] = useState(provider.model); const [region, setRegion] = useState(provider.region); const [key, setKey] = useState(''); const [inputPrice, setInputPrice] = useState(provider.inputPrice); const [outputPrice, setOutputPrice] = useState(provider.outputPrice); const [busy, setBusy] = useState(false); const [result, setResult] = useState(''); const [error, setError] = useState(''); const [removing, setRemoving] = useState(false);
  const [catalogRevision, setCatalogRevision] = useState(0);
  const [priceDrafts,setPriceDrafts]=useState(provider.modelPrices??{[provider.model]:{inputPrice:provider.inputPrice,outputPrice:provider.outputPrice}});
  const subscription=provider.billingMode==='subscription';
  const selectModel=(next:string)=>{setPriceDrafts(old=>({...old,[model]:{inputPrice,outputPrice}}));const price=Object.hasOwn(priceDrafts,next)?priceDrafts[next]:{inputPrice:0,outputPrice:0};setModel(next);setInputPrice(price.inputPrice);setOutputPrice(price.outputPrice);};
  const local = provider.id === 'demo' || provider.id === 'ollama';
  const perform = async (operation: () => Promise<void>) => { setBusy(true); setError(''); setResult(''); try { await operation(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  return <form className="provider-form" onSubmit={e => { e.preventDefault(); void perform(async () => { await save({ ...(label.trim()?{label:label.trim()}:{}),model, region, ...(!subscription?{inputPrice,outputPrice,modelPrices:{...priceDrafts,[model]:{inputPrice,outputPrice}},...(key?{apiKey:key}:{})}:{}) }); setKey(''); setCatalogRevision(n => n + 1); setResult('连接配置已保存'); }); }}><div className="provider-form-title"><h3>{names[provider.id]}</h3><span className={`badge ${local || provider.hasKey ? 'summary' : ''}`}>{subscription?'订阅额度':local ? '本地渠道' : provider.hasKey ? '密钥已配置' : '待配置'}</span></div>{provider.id==='openai'&&<Field label="OpenAI 接入方式"><select value={provider.billingMode??'api'} disabled={busy} onChange={e=>{const billingMode=e.target.value;void perform(()=>save({billingMode}));}}><option value="api">API Key · 按模型单价估算费用</option><option value="subscription">ChatGPT 订阅 · 官方 Codex 授权</option></select></Field>}{subscription?<SubscriptionPanel id={connectionKey(provider)} api={api}/>:provider.id === 'demo' ? <p className="provider-description">使用程序生成的预设回复体验群聊、轮次与停止功能。所有消息均标注「演示」，不会调用真实 AI，也不会产生费用。</p> : provider.id === 'ollama' ? <p className="provider-description">连接本机 Ollama 服务（127.0.0.1:11434）。请先启动 Ollama 并下载模型，再从本机列表选择。模型推理需要本机硬件资源。</p> : provider.id === 'doubao' ? <p className="provider-description">使用火山方舟北京 API。填写方舟 API Key 并从官方参考列表选择已开通模型；专用 ep- 接入点可在高级选项填写。支持按轮讨论、自主群聊与文字技能。豆包网页账号的免费额度不等于 API 额度。</p> : <p className="provider-description">通过供应商官方接口调用模型。密钥留空将保留已保存的密钥；模型费率请参考你的供应商账单。</p>}<Field label="连接名称"><input value={label} maxLength={40} onChange={e=>setLabel(e.target.value)} placeholder="默认连接"/></Field><ModelPicker key={connectionKey(provider) + region} label="默认模型" provider={{ ...provider, region }} value={model} change={selectModel} load={loadModels} disabled={busy} revision={catalogRevision}/><p className="field-help">群成员各自保存模型；修改默认模型不会自动替换已有成员。新密钥先保存，再刷新账号列表。每个模型单独保存单价；切换模型可依次配置，保存连接后一并生效。</p>{!local && !subscription && <Field label="API Key" help={provider.hasKey ? '已保存密钥。输入新值可替换；现有密钥不会显示。' : '仅发送至本地后端保存，不写入聊天记录。'}><input type="password" autoComplete="new-password" spellCheck={false} value={key} onChange={e => setKey(e.target.value)} placeholder={provider.hasKey ? '••••••••（已保存，留空保留）' : '粘贴你的 API Key'}/></Field>}{provider.id === 'qwen' && <Field label="服务地域"><select value={region} onChange={e => setRegion(e.target.value as 'cn' | 'intl')}><option value="cn">中国内地 · 北京</option><option value="intl">国际 · 新加坡</option></select></Field>}{!subscription&&<ModelPricing key={provider.id + model + region} provider={{ ...provider, model, region }} inputUSD={inputPrice} outputUSD={outputPrice} disabled={busy} change={(input, output) => { setInputPrice(input); setOutputPrice(output); }}/>}<label className="toggle-field"><span>启用此连接</span><span className="switch"><input type="checkbox" checked={provider.enabled} disabled={busy} aria-describedby="provider-toggle-help" onChange={e => { const next = e.target.checked; void perform(async () => { await save({ enabled: next }); setResult(next ? '连接已启用并保存' : '连接已停用并保存'); }); }}/><span/></span></label><p id="provider-toggle-help" className="provider-description">启用 / 停用会立即保存。模型名称、密钥与单价修改后，请点击「保存连接」。</p>{error && <p className="inline-error" role="alert">{error}</p>}{result && <p className="inline-success" role="status"><Check size={14}/>{result}</p>}<div className="provider-actions"><button type="button" className="secondary-button" disabled={busy} onClick={() => void perform(async () => { setResult(await test()); })}>{busy ? <LoaderCircle size={14} className="spinning"/> : <RefreshCw size={14}/>}测试已保存连接</button><button className="primary-button" disabled={busy}>保存连接</button></div>{provider.hasKey && !subscription && <button type="button" className="text-button danger" disabled={busy} onClick={() => { if (removing) void perform(async () => { await save({ apiKey: null }); setKey(''); setResult('已移除保存的密钥'); }); else setRemoving(true); }}><Trash2 size={12}/>{removing ? '再次点击确认移除密钥' : '移除已保存密钥'}</button>}{!subscription&&<BillingPanel provider={provider} api={api}/>}</form>;
}
